from .models import GenerateRequest,ProductionPackage,Scene

def build_package(req:GenerateRequest)->ProductionPackage:
    idea=req.idea.strip().rstrip('.!?').capitalize()
    hook=f"At first, it looked like a coincidence. Then the evidence proved that {idea.lower()} was only the beginning."
    titles=[idea,'The Impossible Event Nobody Can Explain',f'This Should Not Exist: {idea}',"Scientists Can't Explain What Happened Next",'The Day Reality Stopped Making Sense']
    thumbs=['A phone displaying impossible evidence while the real scene behind it subtly contradicts the screen.','One enormous impossible event dominating a realistic city, with a tiny human for scale.','A close-up of the evidence with one strange detail revealed through composition, not clutter.']
    beats=['cold open','first evidence','public reaction','expert explanation','contradiction','escalation','second discovery','attempt to test it','test fails','hidden pattern','major reveal','aftermath','final implication']
    n=max(12,req.duration_minutes*2); length=max(20,(req.duration_minutes*60)//n); scenes=[]
    for i in range(n):
        beat=beats[i%len(beats)]
        scenes.append(Scene(number=i+1,duration_seconds=length,purpose=beat,narration=f'[{beat.upper()}] Develop {idea} with one concrete new piece of evidence. Keep the narrator calm, specific and believable.',visual_prompt=f'Cinematic photorealistic mystery documentary, believable modern environment, realistic people, natural physics, dramatic but restrained lighting, atmospheric depth, varied composition, visualizing {idea}; beat: {beat}; no text, no watermark.',camera='Mix wide establishing shots, medium observational shots and controlled close-ups.',sound='Low atmospheric bed, environmental audio, restrained impact on new evidence, silence before major reveals.'))
    script=f'OPENING\n{hook}\n\nSTORY\nThis is an original narrative blueprint about {idea}. Move from evidence to doubt to escalation, then reveal a pattern that changes the meaning of the opening event.\n\nENDING\nFinish with a meaningful unanswered implication that makes the viewer reconsider the first 30 seconds.'
    shorts=[{'title':f'{idea} — Part {i+1}','hook':'What if the impossible evidence was real?','script':f'Open with the strangest evidence from {idea}, reveal one escalation, then cut before the full explanation.','visual_plan':'3–5 fast cinematic shots from the long-form plan.','cta':'Watch the full story for the explanation.'} for i in range(req.shorts_count)]
    return ProductionPackage(concept=idea,titles=titles,hook=hook,thumbnail_concepts=thumbs,script=script,scenes=scenes,editing_plan=['Open on evidence immediately; no greeting or channel intro.','Change framing every 2–6 seconds during high-retention sections.','Use silence immediately before major reveals.','Keep captions readable and minimal.','Use original/generated visuals and properly licensed music/SFX.','Make every episode a distinct story, not a repetitive slideshow template.'],shorts=shorts,quality_check=['Original premise and narration.','No copied footage or copyrighted clips.','Do not present unsupported claims as real-world fact.','Clear escalation and payoff.','Visuals support narration and vary by scene.','Human review before publishing.'])
